    """Create a new model in Amazon SageMaker"""
    response = sagemaker_client.create_model(
        ModelName=model_name,
        ExecutionRoleArn='arn:aws:iam::123456789012:role/SageMakerRole',
        PrimaryContainer=primary_container
    )
    return response

